using ImportOps.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ImportOps.Infrastructure.Persistence.Configurations;

internal sealed class QuotationSupplierConfiguration : IEntityTypeConfiguration<QuotationSupplier>
{
    public void Configure(EntityTypeBuilder<QuotationSupplier> b) { b.ToTable("QUOTATION_SUPPLIER","sales"); b.HasKey(x=>x.QuotationSupplierId); b.Property(x=>x.QuotationSupplierId).HasColumnName("quotation_supplier_id"); b.Property(x=>x.QuotationId).HasColumnName("quotation_id"); b.Property(x=>x.SupplierId).HasColumnName("supplier_id"); b.Property(x=>x.DisplayOrder).HasColumnName("display_order"); b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(500); b.HasOne(x=>x.Supplier).WithMany().HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Restrict); }
}
internal sealed class QuotationCargoItemConfiguration : IEntityTypeConfiguration<QuotationCargoItem>
{
    public void Configure(EntityTypeBuilder<QuotationCargoItem> b) { b.ToTable("QUOTATION_CARGO_ITEM","sales"); b.HasKey(x=>x.QuotationCargoItemId); b.Property(x=>x.QuotationCargoItemId).HasColumnName("quotation_cargo_item_id"); b.Property(x=>x.QuotationId).HasColumnName("quotation_id"); b.Property(x=>x.QuotationSupplierId).HasColumnName("quotation_supplier_id"); b.Property(x=>x.LineNo).HasColumnName("line_no"); b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(500); b.Property(x=>x.Quantity).HasColumnName("quantity").HasColumnType("decimal(18,4)"); b.Property(x=>x.UnitOfMeasure).HasColumnName("unit_of_measure").HasMaxLength(30); b.Property(x=>x.NetWeightKg).HasColumnName("net_weight_kg").HasColumnType("decimal(18,3)"); b.Property(x=>x.GrossWeightKg).HasColumnName("gross_weight_kg").HasColumnType("decimal(18,3)"); b.Property(x=>x.VolumeM3).HasColumnName("volume_m3").HasColumnType("decimal(18,4)"); b.Property(x=>x.DeclaredValue).HasColumnName("declared_value").HasColumnType("decimal(19,4)"); b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength(); b.Property(x=>x.OriginCountryCode).HasColumnName("origin_country_code").HasMaxLength(2).IsFixedLength(); b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(500); b.HasOne(x=>x.QuotationSupplier).WithMany(x=>x.CargoItems).HasForeignKey(x=>x.QuotationSupplierId).OnDelete(DeleteBehavior.Restrict); }
}
internal sealed class QuotationCustomsTaxConfiguration : IEntityTypeConfiguration<QuotationCustomsTax>
{
    public void Configure(EntityTypeBuilder<QuotationCustomsTax> b) { b.ToTable("QUOTATION_CUSTOMS_TAX","sales"); b.HasKey(x=>x.QuotationCustomsTaxId); b.Property(x=>x.QuotationCustomsTaxId).HasColumnName("quotation_customs_tax_id"); b.Property(x=>x.QuotationId).HasColumnName("quotation_id"); b.Property(x=>x.TaxCode).HasColumnName("tax_code").HasMaxLength(40).IsUnicode(false); b.Property(x=>x.CustomsTaxConceptId).HasColumnName("customs_tax_concept_id"); b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(160); b.Property(x=>x.Amount).HasColumnName("amount").HasColumnType("decimal(19,4)"); b.Property(x=>x.RateApplied).HasColumnName("rate_applied").HasColumnType("decimal(9,4)"); b.Property(x=>x.CalculationBase).HasColumnName("calculation_base").HasColumnType("decimal(19,4)"); b.Property(x=>x.IsCalculated).HasColumnName("is_calculated"); b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength(); b.Property(x=>x.DisplayOrder).HasColumnName("display_order"); b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(500); b.HasOne(x=>x.CustomsTaxConcept).WithMany().HasForeignKey(x=>x.CustomsTaxConceptId).OnDelete(DeleteBehavior.Restrict); }
}
internal sealed class QuotationConceptConfiguration : IEntityTypeConfiguration<QuotationConcept>
{
    public void Configure(EntityTypeBuilder<QuotationConcept> b) { b.ToTable("QUOTATION_CONCEPT","cfg"); b.HasKey(x=>x.QuotationConceptId); b.Property(x=>x.QuotationConceptId).HasColumnName("quotation_concept_id"); b.Property(x=>x.CompanyId).HasColumnName("company_id"); b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50).IsUnicode(false); b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(160); b.Property(x=>x.GroupCode).HasColumnName("group_code").HasMaxLength(30).IsUnicode(false); b.Property(x=>x.GroupName).HasColumnName("group_name").HasMaxLength(120); b.Property(x=>x.ServiceCategoryId).HasColumnName("service_category_id"); b.Property(x=>x.ExpenseCategoryId).HasColumnName("expense_category_id"); b.Property(x=>x.DefaultTaxRate).HasColumnName("default_tax_rate").HasColumnType("decimal(9,4)"); b.Property(x=>x.IsTaxable).HasColumnName("is_taxable"); b.Property(x=>x.IsRebillableDefault).HasColumnName("is_rebillable_default"); b.Property(x=>x.DisplayOrder).HasColumnName("display_order"); b.Property(x=>x.IsActive).HasColumnName("is_active"); b.Property(x=>x.CreatedAt).HasColumnName("created_at"); b.Property(x=>x.ModifiedAt).HasColumnName("modified_at"); }
}
internal sealed class CompanyBankAccountConfiguration : IEntityTypeConfiguration<CompanyBankAccount>
{
    public void Configure(EntityTypeBuilder<CompanyBankAccount> b) { b.ToTable("COMPANY_BANK_ACCOUNT","cfg"); b.HasKey(x=>x.CompanyBankAccountId); b.Property(x=>x.CompanyBankAccountId).HasColumnName("company_bank_account_id"); b.Property(x=>x.CompanyId).HasColumnName("company_id"); b.Property(x=>x.BankName).HasColumnName("bank_name").HasMaxLength(160); b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength(); b.Property(x=>x.AccountNumber).HasColumnName("account_number").HasMaxLength(80); b.Property(x=>x.Cci).HasColumnName("cci").HasMaxLength(80); b.Property(x=>x.AccountHolder).HasColumnName("account_holder").HasMaxLength(200); b.Property(x=>x.DisplayOrder).HasColumnName("display_order"); b.Property(x=>x.ShowOnQuotation).HasColumnName("show_on_quotation"); b.Property(x=>x.IsActive).HasColumnName("is_active"); b.Property(x=>x.CreatedAt).HasColumnName("created_at"); b.Property(x=>x.ModifiedAt).HasColumnName("modified_at"); }
}
